    "spec": {
      "containers": [
        {
          "name": "app",
          "args": ["sleep", "3600"],
          "env": [
            {
              "name": "CONFIG_MAP_DATA",
              "valueFrom": {
                "configMapKeyRef": {
                  "name": "app-config",
